from pathlib import Path
import re

path = Path('/home/ubuntu/devora-frontend/client/src/pages/Home.tsx')
text = path.read_text()

text = text.replace('<Logo compact />', '<Logo />', 1)
text = text.replace('Team admin</small>', 'Team Admin</small>')

new_dashboard = r'''function DeveloperDashboard({ onView, onModule }: { onView: (view: View) => void; onModule: () => void }) {
  const [showPriorityActions, setShowPriorityActions] = useState(false);
  const actions = ["Finish the Local Setup checkpoint.", "Review the API glossary with Bob.", "Complete the Architecture module questions."];
  return <div className="dashboard-grid"><section className="primary-column"><div className="signal-card priority"><div className="card-top"><div><span className="eyebrow seafoam">HIGHEST PRIORITY ACTION</span><h2>{showPriorityActions ? actions[1] : actions[0]}</h2></div><button className={`round-btn ${showPriorityActions ? "rotated" : ""}`} onClick={() => setShowPriorityActions((current) => !current)} aria-label="Show next priority actions"><ChevronDown size={17} /></button></div><p>{showPriorityActions ? "A clear next step for staying aligned with the team’s shared context." : "Complete the reading, then answer two questions so Bob can unlock Architecture."}</p><div className="action-meta"><span><Zap size={14} /> {showPriorityActions ? "22 min estimated" : "18 min remaining"}</span><button onClick={onModule}>{showPriorityActions ? "Open learning path" : "Continue module"} <ArrowUpRight size={14} /></button></div>{showPriorityActions && <div className="priority-list">{actions.map((action, index) => <button key={action} onClick={() => index === 0 ? onModule() : toast("This action will connect to your project feed.")}><span>{String(index + 1).padStart(2, "0")}</span><strong>{action}</strong><ChevronRight size={14} /></button>)}</div>}</div><div className="section-head"><div><span className="eyebrow">YOUR PATH</span><h2>Keep the context flowing.</h2></div><button className="text-btn" onClick={() => onView("learning")}>View all <ArrowUpRight size={14} /></button></div><div className="path-preview">{modules.slice(0, 3).map((module) => <button key={module.title} onClick={onModule} className={`path-row ${module.status}`}><span className="module-num">{module.status === "complete" ? <Check size={15} /> : module.status === "locked" ? <LockKeyhole size={14} /> : module.tag}</span><span className="path-info"><strong>{module.title}</strong><small>{module.desc}</small></span><span className="path-time">{module.time}</span><ChevronRight size={16} /></button>)}</div></section><aside className="secondary-column"><div className="mini-panel"><div className="section-head"><div><span className="eyebrow">PROJECT RESOURCES</span><h3>Everything in one place.</h3></div><MoreHorizontal size={17} /></div><a className="resource-link" href="https://github.com" target="_blank" rel="noreferrer"><div className="resource-icon github"><Github size={17} /></div><span><strong>GitHub repository</strong><small>ctrlaltelite / atlas-core</small></span><ArrowUpRight size={15} /></a><button className="resource-link" onClick={() => onView("documentation")}><div className="resource-icon docs"><FileText size={17} /></div><span><strong>Company documentation</strong><small>12 files · updated today</small></span><ArrowUpRight size={15} /></button></div><NotesPreview onView={onView} /></aside></div>;
}'''
text = re.sub(r'function DeveloperDashboard\(.*?\nfunction NotesPreview', new_dashboard + '\nfunction NotesPreview', text, flags=re.S)

new_learning = r'''function LearningPath({ selectedModule, setSelectedModule, quizPassed, setQuizPassed, quizAnswer, setQuizAnswer, showHint, setShowHint, onBobFeedback }: { selectedModule: number; setSelectedModule: (value: number) => void; quizPassed: boolean; setQuizPassed: (value: boolean) => void; quizAnswer: string | null; setQuizAnswer: (value: string | null) => void; showHint: boolean; setShowHint: (value: boolean) => void; onBobFeedback: (value: "idle" | "wrong" | "correct") => void }) {
  const [started, setStarted] = useState(false);
  const [activeQuestion, setActiveQuestion] = useState(0);
  const [answers, setAnswers] = useState<Record<number, string | null>>({});
  const [notes, setNotes] = useState("");
  const mod = modules[selectedModule];
  const questions = [{ prompt: "Which command installs the project dependencies?", options: ["npm start", "pnpm install", "git pull", "node setup.js"], correct: "pnpm install", explanation: "pnpm install keeps the dependency graph reproducible across the team." }, { prompt: "Where should local environment values live?", options: ["README.md", ".env.local", "package.json", "src/index.ts"], correct: ".env.local", explanation: "The local environment file keeps machine-specific values out of the shared source." }];
  const question = questions[activeQuestion];
  const triggerBob = (feedback: "wrong" | "correct") => { onBobFeedback("idle"); window.setTimeout(() => onBobFeedback(feedback), 20); };
  const choose = (answer: string) => {
    setAnswers((current) => ({ ...current, [activeQuestion]: answer })); setQuizAnswer(answer);
    if (answer === question.correct) {
      triggerBob("correct");
      if (activeQuestion === questions.length - 1) { setQuizPassed(true); toast.success("Good job — the next module is unlocked."); }
      else { window.setTimeout(() => { setActiveQuestion(1); setQuizAnswer(null); }, 500); }
    } else { setShowHint(false); triggerBob("wrong"); toast("Try again — Bob has a hint when you need it."); }
  };
  const completed = (index: number) => index === 0 || (index === 1 && quizPassed);
  const locked = (index: number) => index > 1 && !quizPassed;
  return <><div className="page-heading"><div><p className="eyebrow">ONBOARDING / {quizPassed ? "100% COMPLETE" : "72% COMPLETE"}</p><h1>Learning path</h1><p>A guided route through the parts of Atlas Core that matter most to your role.</p></div><div className="progress-summary"><ProgressRing value={quizPassed ? 100 : 72} /><span><strong>{quizPassed ? "5 of 5" : "3 of 5"}</strong><small>modules completed</small></span></div></div><div className={`learning-layout ${started ? "is-reading" : ""}`}><div className="module-list"><div className="eyebrow">YOUR MODULES</div>{modules.map((item, index) => <button key={item.title} className={`module-item ${index === selectedModule ? "selected" : ""} ${locked(index) ? "locked" : ""}`} onClick={() => { if (!locked(index)) { setSelectedModule(index); setStarted(false); setActiveQuestion(0); setQuizAnswer(null); } }}><span className="module-num">{completed(index) ? <Check size={14} /> : locked(index) ? <LockKeyhole size={13} /> : item.tag}</span><span><strong>{item.title}</strong><small>{item.time} · {completed(index) ? "Completed" : locked(index) ? "Locked" : index === selectedModule && started ? "In progress" : "Ready to start"}</small></span><ChevronRight size={15} /></button>)}</div><section className={`module-detail ${started ? "reading-mode" : ""}`}>{!started ? <><div className="module-detail-head"><div><span className="eyebrow seafoam">MODULE {mod.tag} / {completed(selectedModule) ? "COMPLETE" : "READY"}</span><h2>{mod.title}</h2><p>{mod.desc}</p></div><div className="module-time"><Zap size={15} /> {mod.time}</div></div><div className="module-progress"><span style={{ width: completed(selectedModule) ? "100%" : "62%" }} /></div><div className="module-summary"><span className="summary-mark"><BookOpen size={20} /></span><div><span className="eyebrow">MODULE SUMMARY</span><h3>{selectedModule === 1 ? "A calm first step into the codebase." : "Build the context you need."}</h3><p>{selectedModule === 1 ? "Learn the environment contract, the commands the team trusts, and how to verify a clean local session before touching product logic." : mod.desc}</p><div className="summary-meta"><span><Zap size={14} /> {mod.time}</span><span><CircleHelp size={14} /> {selectedModule === 1 ? "2 questions" : "Reading + checkpoint"}</span></div><button className="primary-cta" onClick={() => setStarted(true)}>{completed(selectedModule) ? "Review module" : "Start module"} <ArrowUpRight size={15} /></button></div></div></> : <div className="module-reading-wrap"><div className="module-reading"><div className="reading-toolbar"><button className="text-btn" onClick={() => setStarted(false)}><ChevronRight size={14} className="back-chevron" /> Return to Learning path</button><span className="eyebrow">MODULE {mod.tag} / READING MODE</span></div><div className="module-reading-head"><span className="eyebrow seafoam">ATLAS CORE / LOCAL SETUP</span><h2>{mod.title}</h2><p>Make the first local run feel predictable.</p></div><div className="reading-copy"><p className="lead">The fastest way into Atlas Core is to understand the environment contract before you touch the product logic.</p><p>This module connects the repository shape to a working local session. You will learn the package manager, environment variables, and the commands the team uses to verify a clean setup.</p><div className="command-block"><span>TERMINAL</span><code><i>$</i> pnpm install<br /><i>$</i> pnpm dev</code></div><h3>Before you move on</h3><p>Keep your local values in the environment file, then use the checkpoint below to confirm the two details that make this project predictable.</p></div><div className="quiz-card"><div className="quiz-title"><span className="eyebrow">CHECKPOINT / 0{activeQuestion + 1} OF 02</span><h3>{question.prompt}</h3></div><div className="quiz-options">{question.options.map((answer) => <button key={answer} className={answers[activeQuestion] === answer ? answer === question.correct ? "correct" : "wrong" : ""} onClick={() => choose(answer)}>{answer}<span>{answers[activeQuestion] === answer && (answer === question.correct ? <Check size={15} /> : "×")}</span></button>)}</div>{quizAnswer && quizAnswer !== question.correct && <div className="quiz-feedback wrong-feedback"><strong>Try again — you got this!</strong><button onClick={() => setShowHint(true)}>Want a hint?</button></div>}{showHint && <div className="quiz-feedback hint-feedback"><Sparkles size={15} /><span>{activeQuestion === 0 ? "Look for the package manager named in the terminal snippet above." : "Keep machine-specific values out of shared source files."}</span></div>}{quizPassed && <div className="quiz-feedback correct-feedback"><Check size={15} /><span><strong>Good job.</strong> Both questions are complete and the next module is unlocked.</span></div>}</div></div><aside className="module-notes"><div className="section-head"><div><span className="eyebrow">PRIVATE NOTES</span><h3>Keep a thought here.</h3></div><MoreHorizontal size={17} /></div><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Write anything you want to remember..." /><span className="notes-hint">Saved locally in this demo</span></aside></div>}</section></div></>;
}'''
text = re.sub(r'function LearningPath\(.*?\nfunction Documentation', new_learning + '\nfunction Documentation', text, flags=re.S)

new_modal = r'''function ProjectModal({ onClose }: { onClose: () => void }) { return <div className="modal-backdrop" onClick={onClose}><div className="project-modal" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">PROJECT / ATLAS CORE</span><h2>Project details</h2></div><button className="icon-btn" onClick={onClose}><X size={18} /></button></div><p className="modal-intro">A shared map of what the team is building, who owns it, and how the pieces connect.</p><div className="detail-grid"><div><span className="eyebrow">ABOUT</span><p>Atlas Core is the shared knowledge layer for CtrlAltElite’s engineering team. It turns repository context into a clear sequence of questions, modules, and practical next steps for every new developer.</p></div><div><span className="eyebrow">TECHNOLOGY</span><p>React and Node power the product surface, PostgreSQL keeps the workspace grounded, and the Knowledge Engine connects documentation with project-specific answers.</p></div><div><span className="eyebrow">TEAM</span><p>Four contributors are currently mapped to Atlas Core, with Jordan Patel coordinating the admin workspace and onboarding priorities.</p></div><div><span className="eyebrow">FLOW</span><p>Repository and docs are ingested, the system understands the project, knowledge gaps are mapped, and each developer gets a guided route forward.</p></div></div></div></div>; }'''
text = re.sub(r'function ProjectModal\(.*?$', new_modal, text, flags=re.S)

path.write_text(text)
print('updated Home.tsx')
